// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.brain.skill.routerimport com.roshan.persona.brain.bus.BrainBusimport com.roshan.persona.brain.bus.BrainEventimport com.roshan.persona.brain.context.BrainContextimport com.roshan.persona.brain.intent.CompoundExecutorimport com.roshan.persona.brain.intent.Intentimport com.roshan.persona.brain.skill.BrainSkillimport com.roshan.persona.brain.skill.SkillContextimport com.roshan.persona.brain.skill.SkillDispatchersimport com.roshan.persona.brain.skill.SkillOutputimport com.roshan.persona.brain.skill.executor.SystemOperationExecutorimport com.roshan.persona.brain.skill.registry.SkillRegistryimport com.roshan.persona.common.AppErrorimport com.roshan.persona.common.Resultimport kotlinx.coroutines.asyncimport kotlinx.coroutines.awaitAllimport kotlinx.coroutines.coroutineScopeimport kotlinx.coroutines.withContextimport kotlinx.coroutines.withTimeoutOrNullimport kotlinx.coroutines.CoroutineDispatcherimport kotlinx.coroutines.Dispatchersimport kotlinx.coroutines.asCoroutineDispatcherimport timber.log.Timberimport javax.inject.Injectimport javax.inject.Singleton/** * NOUS — Layer 2: Skill Router. * * Routes classified [Intent]s to matching [BrainSkill]s. Key responsibilities: * *   1. **Skill selection** — find skills whose `supportedIntents` match the *      classified intent. Rank by persona preference + historical success rate. *   2. **Permission handling** (Fixes #20) — if a matching skill is found but *      required permissions are missing, return [SkillOutput.NeedsPermission] *      (NOT defer to LLM). Brain emits [BrainEvent.SkillNeedsPermission] so *      UI shows the permission prompt. *   3. **Compound intent execution** (Fixes #23) — handle [Intent.Compound] *      with SEQUENTIAL / PARALLEL / CONDITIONAL executors. *   4. **Timeout enforcement** — each skill declares its own timeout. If *      exceeded, return [SkillOutput.Failure] with [AppError.Skill.TimedOut]. *   5. **Error resilience** — skill crashes don't crash the brain. Caught *      and returned as [SkillOutput.Failure]. * * Performance budget: p50 < 20ms (dispatch), p95 < 50ms (dispatch + first action). * * @see <a href="docs/spec/module2-spec-review.pdf">§6 Layer 2</a> */@Singletonclass SkillRouter @Inject constructor(    private val skillRegistry: SkillRegistry,    private val permissionChecker: PermissionChecker,    private val systemOperationExecutor: SystemOperationExecutor,    private val skillDispatchers: SkillDispatchers,    private val brainBus: BrainBus,    private val credentialVault: com.roshan.persona.brain.skill.CredentialVaultInterface,) {    /**     * Route [intent] to the best matching skill.     *     * @return [Result] containing [SkillOutput], or [Result.Failure] if no     *         skill matched and caller should defer to Layer 3.     */    suspend fun route(        intent: Intent,        context: BrainContext,    ): Result<SkillOutput> {        // Handle compound intents separately        if (intent is Intent.Compound) {            return routeCompound(intent, context)        }        return routeSingle(intent, context)    }    /** Route a single (non-compound) intent. */    private suspend fun routeSingle(        intent: Intent,        context: BrainContext,    ): Result<SkillOutput> {        val candidates = skillRegistry.findSkillsForIntent(intent::class)        if (candidates.isEmpty()) {            Timber.tag("NOUS.L2").v("No skill found for ${intent::class.simpleName} — defer to L3")            return Result.Failure(                error = AppError.Skill.NotFound(intent::class.simpleName ?: "unknown"),                correlationId = context.correlationId,                durationNanos = 0,            )        }        // Rank candidates: persona preference > success rate > latency        val ranked = rankSkills(candidates, context)        val bestSkill = ranked.first()        // Check permissions (Fixes #20 — return NeedsPermission, NOT defer)        val missingPerms = permissionChecker.findMissing(bestSkill.requiredPermissions)        if (missingPerms.isNotEmpty()) {            Timber.tag("NOUS.L2").v(                "Skill %s needs permissions: %s",                bestSkill.id,                missingPerms.joinToString(),            )            // Emit event so UI shows permission prompt            brainBus.emit(                BrainEvent.SkillNeedsPermission(                    skillId = bestSkill.id,                    permission = missingPerms.first(),                    correlationId = context.correlationId,                ),            )            return Result.Success(                data = SkillOutput.NeedsPermission(                    skillId = bestSkill.id,                    missingPermissions = missingPerms.toList(),                    userMessage = "I can do this, but I need ${missingPerms.first()} permission.",                ),                correlationId = context.correlationId,                durationNanos = 0,            )        }        // Execute the skill        return executeSkill(bestSkill, intent, context)    }    /** Route a compound intent (Fixes #23). */    private suspend fun routeCompound(        intent: Intent.Compound,        context: BrainContext,    ): Result<SkillOutput> {        Timber.tag("NOUS.L2").v(            "Routing compound intent: %d sub-intents, executor=%s",            intent.intents.size,            intent.executor,        )        return when (intent.executor) {            CompoundExecutor.SEQUENTIAL -> executeSequential(intent.intents, context)            CompoundExecutor.PARALLEL -> executeParallel(intent.intents, context)            CompoundExecutor.CONDITIONAL -> executeConditional(intent.intents, context)        }    }    /** Execute sub-intents sequentially. */    private suspend fun executeSequential(        intents: List<Intent>,        context: BrainContext,    ): Result<SkillOutput> {        val results = mutableListOf<Result<SkillOutput>>()        val warnings = mutableListOf<String>()        for (subIntent in intents) {            val result = routeSingle(subIntent, context)            results.add(result)            when (result) {                is Result.Failure -> warnings.add("Step failed: ${result.error.message}")                is Result.Success -> {                    val data = result.data                    when (data) {                        is SkillOutput.Partial -> warnings.addAll(data.warnings)                        is SkillOutput.Failure -> warnings.add(data.error.message)                        is SkillOutput.NeedsPermission -> warnings.add("Permission needed: ${data.userMessage}")                        is SkillOutput.NeedsInput -> warnings.add("Input needed: ${data.prompt}")                        is SkillOutput.Success -> { /* ok */ }                    }                }                is Result.Partial -> warnings.addAll(result.warnings)            }        }        val successCount = results.count { r ->            r is Result.Success && r.data is SkillOutput.Success        }        val total = intents.size        val resultData = results.map { r ->            when (r) {                is Result.Success -> r.data                else -> null            }        }        return if (successCount == total) {            Result.Success(                data = SkillOutput.Success(                    message = "Done — $total actions completed.",                    data = mapOf("results" to resultData),                ),                correlationId = context.correlationId,                durationNanos = 0,            )        } else {            Result.Success(                data = SkillOutput.Partial(                    message = "Completed $successCount of $total",                    warnings = warnings,                    data = mapOf("results" to resultData),                ),                correlationId = context.correlationId,                durationNanos = 0,            )        }    }    /** Execute sub-intents in parallel using bounded dispatcher (ANR-safe). */    private suspend fun executeParallel(        intents: List<Intent>,        context: BrainContext,    ): Result<SkillOutput> = withContext(PARALLEL_DISPATCHER) {        coroutineScope {            val results = intents.map { subIntent ->                async { routeSingle(subIntent, context) }            }.awaitAll()        val successCount = results.count { r ->            r is Result.Success && r.data is SkillOutput.Success        }        val total = intents.size        val warnings = results.mapNotNull { result ->            when (result) {                is Result.Failure -> "Step failed: ${result.error.message}"                is Result.Success -> {                    val data = result.data                    when (data) {                        is SkillOutput.Partial -> data.warnings.joinToString()                        is SkillOutput.Failure -> data.error.message                        else -> null                    }                }                is Result.Partial -> result.warnings.joinToString()            }        }        val resultData = results.map { r ->            when (r) {                is Result.Success -> r.data                else -> null            }        }        if (successCount == total) {            Result.Success(                data = SkillOutput.Success(                    message = "Done — $total actions completed in parallel.",                    data = mapOf("results" to resultData),                ),                correlationId = context.correlationId,                durationNanos = 0,            )        } else {            Result.Success(                data = SkillOutput.Partial(                    message = "Completed $successCount of $total in parallel",                    warnings = warnings,                    data = mapOf("results" to resultData),                ),                correlationId = context.correlationId,                durationNanos = 0,            )        }        }  // close coroutineScope    }  // close withContext    /** Execute conditional: first intent is condition, rest execute if condition succeeds. */    private suspend fun executeConditional(        intents: List<Intent>,        context: BrainContext,    ): Result<SkillOutput> {        if (intents.size < 2) {            return Result.Success(                data = SkillOutput.Failure(                    error = AppError.Skill.Crashed(                        skillName = "conditional",                        cause = IllegalArgumentException("Conditional needs at least 2 intents"),                    ),                    userMessage = "Conditional execution requires a condition and an action.",                ),                correlationId = context.correlationId,                durationNanos = 0,            )        }        val conditionIntent = intents.first()        val actionIntents = intents.drop(1)        // Execute condition first        val conditionResult = routeSingle(conditionIntent, context)        val conditionSucceeded = when (conditionResult) {            is Result.Success -> conditionResult.data is SkillOutput.Success            else -> false        }        if (!conditionSucceeded) {            val conditionData = when (conditionResult) {                is Result.Success -> conditionResult.data                else -> null            }            return Result.Success(                data = SkillOutput.Success(                    message = "Condition not met — skipping action.",                    data = mapOf("conditionResult" to conditionData),                ),                correlationId = context.correlationId,                durationNanos = 0,            )        }        // Condition met — execute actions        return executeSequential(actionIntents, context)    }    /** Rank candidate skills by persona preference, success rate, latency. */    private fun rankSkills(candidates: List<BrainSkill>, context: BrainContext): List<BrainSkill> {        val personaPrefs = context.activePersona.skillPreferences        val userPrefs = context.userContext.skillPreferences        return candidates.sortedWith(            compareByDescending<BrainSkill> { skill ->                // Persona preference weight (0.0-1.0)                val personaWeight = personaPrefs[skill.id] ?: 0.5f                // User preference weight (0.0-1.0)                val userWeight = userPrefs[skill.id]?.weight ?: 0.5f                // Combined score                personaWeight * 0.6f + userWeight * 0.4f            }.thenBy { skill ->                // Lower timeout = faster (prefer faster skills)                skill.timeoutMs            }.thenBy { skill ->                // Deterministic tiebreak                skill.id            },        )    }    /** Execute a single skill with timeout + error handling. */    private suspend fun executeSkill(        skill: BrainSkill,        intent: Intent,        context: BrainContext,    ): Result<SkillOutput> {        val skillContext = SkillContext(            brainContext = context,            dispatchers = skillDispatchers,            brainBus = brainBus,            credentialVault = credentialVault,        )        // Emit SkillInvoked event        brainBus.emit(            BrainEvent.SkillInvoked(                skillId = skill.id,                intentLabel = intent::class.simpleName ?: "unknown",                correlationId = context.correlationId,            ),        )        val startNanos = System.nanoTime()        // Execute with timeout        val result = withTimeoutOrNull(skill.timeoutMs) {            try {                skill.execute(intent, skillContext)            } catch (t: Throwable) {                Timber.tag("NOUS.L2").e(t, "Skill %s threw", skill.id)                Result.Failure(                    error = AppError.Skill.Crashed(skillName = skill.id, cause = t),                    correlationId = context.correlationId,                    durationNanos = System.nanoTime() - startNanos,                )            }        }        val durationMs = (System.nanoTime() - startNanos) / 1_000_000        return when {            result == null -> {                Timber.tag("NOUS.L2").w("Skill %s timed out after %dms", skill.id, skill.timeoutMs)                Result.Success(                    data = SkillOutput.Failure(                        error = AppError.Skill.TimedOut(                            skillName = skill.id,                            durationMs = skill.timeoutMs,                        ),                        userMessage = "The operation took too long.",                    ),                    correlationId = context.correlationId,                    durationNanos = System.nanoTime() - startNanos,                )            }            result is Result.Failure -> {                Result.Success(                    data = SkillOutput.Failure(                        error = result.error,                        userMessage = null,                    ),                    correlationId = context.correlationId,                    durationNanos = result.durationNanos,                )            }            result is Result.Success -> {                Timber.tag("NOUS.L2").v("Skill %s completed in %dms", skill.id, durationMs)                result            }            result is Result.Partial -> {                Result.Success(                    data = SkillOutput.Partial(                        message = "Partial result",                        warnings = result.warnings,                    ),                    correlationId = context.correlationId,                    durationNanos = result.durationNanos,                )            }            else -> result        }    }    companion object {        /**         * Bounded dispatcher for parallel skill execution (ANR-safe).         *         * Prevents parallel skills from blocking the main thread or         * overwhelming the system with too many concurrent operations.         * Limited to 4 threads (enough for parallel skills, not enough         * to cause resource exhaustion).         */        private val PARALLEL_DISPATCHER: CoroutineDispatcher =            java.util.concurrent.Executors                .newFixedThreadPool(4) { runnable ->                    Thread(runnable, "nous-skill-parallel").apply { isDaemon = true }                }                .asCoroutineDispatcher()    }}